as \\"Employer Address Pin Code\\", ''NA'' as \\"Employer Address Locality\\", ''NA'' as \\"Employer Address State\\", ''NA'' as \\"Employer Address District\\", ''NA'' as \\"Employer Address City\\", json_extract_scalar(vcattribs, ''$.dateOfRegistration'') as \\"Date of Customer On-boarding\\", ''NA'' as \\"Date of Last KYC / re-KYC\\", ''NA'' as \\"Customer Risk Level\\", ''NA'' as \\"NPR\\", ''NA'' as \\"PEKRN\\", ''NA'' as \\"Primary State Name\\", ''NA'' as \\"Primary District Name\\", ''NA'' as \\"Primary City Name\\", ''NA'' as \\"Secondary State Name\\", ''NA'' as \\"Secondary District Name\\", ''NA'' as \\"Secondary City Name\\", ''NA'' as \\"Employee State Name\\", ''NA'' as \\"Employee District Name\\", ''NA'' as \\"Employee City Name\\", ''NA'' as \\"Other Customer Type\\", :Group as \\"Report Type\\" from t17refined.masters.customers where vcexternalcustid = :Address and itenantid = :tenantid",
