        "Account Person Detail" : "select :Group as \\"Report Type\\", vcaccount as \\"Account Number\\", ''NA'' as \\"Relationship Type\\", vcexternalaccountid as \\"Unique Reference Number\\", ''NA'' as \\"Individual / Non-individual\\", ''NA'' as \\"Name of Non-customer\\" from t17refined.masters.accounts where itenantid = :tenantid and vcexternalaccountid = :Address",
